请对以下 case 进行三维加权评分。

=== case_id ===
Case-07-sports-event-122

=== 用户原始指令 (query.txt) ===
帮我弄个足球倒计时卡片,字压在背景图上,点一下跳应用,提醒我快来不及

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我弄个足球倒计时卡片,字压在背景图上,点一下跳应用,提醒我快来不及",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.calendar",
        "abilityName": "com.huawei.calendar.MainAbility",
        "uri": "calendar://event/football-122"
      }
    }
  ],
  "dataModel": {
    "value": {
      "match": {
        "title": "足球倒计时",
        "kickoff": "今晚 19:35 开赛",
        "alert": "快来不及",
        "countdownLabel": "距离开赛",
        "countdown": "18 分钟",
        "actionText": "跳应用",
        "background": "assets/football-countdown-bg.png"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "football_background",
      "src": "assets/football-countdown-bg.png",
      "use": "football countdown background",
      "description": "足球赛事背景图素材，用作整张倒计时提醒卡片的底图，适合承载压字和紧迫赛前氛围。",
      "bindTo": "/match/background"
    }
  ]
}

